(()=>{'use strict';
const $=id=>document.getElementById(id);
const products=[{"id":"gv","name":"Great Value Chocolate Fudge Fiber Brownie Baked Bars, Value Pack, 0.89 oz, 12 Count","size":"12 count · 10.6 oz pack","cal":90,"fiber":5,"serving":"1 bar (25 g)","price":"5.72","tags":"fiber brownies chocolate baked snack Great Value","image":"gv-front-display.svg","photoSourceLabel":"Walmart","productSource":"https://www.walmart.com/ip/Great-Value-Chocolate-Fudge-Fiber-Brownie-Baked-Bars-Value-Pack-0-89-oz-12-Count/163790745","nutritionSource":"https://i5.walmartimages.com/asr/1514b573-c57a-4835-af87-f264743d9074.9560a5874517ac74943e37f8da8df3fc.jpeg?odnBg=FFFFFF&odnHeight=573&odnWidth=573","note":"Product and label snapshot verified October 6, 2026. Check the current package.","unitPrice":"54.0¢/oz","rating":4.7,"reviewCount":586,"reviewText":"586 reviews","shortDescription":"12 count · 25 g per labeled serving","shoppingNotes":["Walmart title says 0.89 oz per brownie, but front pack photo says 0.88 oz (25g). Serving label confirms 25g.","Prices and written-review counts are source snapshots, not live local offers."]},{"id":"fiber-one","name":"Fiber One Soft Baked Chocolate Fudge Brownies, Fiber Snacks, Mega Pack, 18 Ct, 16 oz","size":"18 count · 16 oz pack","cal":70,"fiber":7,"serving":"1 brownie (25 g)","price":"9.83","tags":"fiber brownies chocolate baked snack Fiber One","image":"fiber-one-front-display.svg","photoSourceLabel":"Walmart","productSource":"https://www.walmart.com/ip/Fiber-One-70-Calorie-Brownies-Chocolate-Fudge-Snack-Bars-Mega-Pack-18-Bars-16-oz/25847970","nutritionSource":"https://assets.syndigo.com/8e1e9911-f803-447f-944c-c576be44273e?numRatio=1&denRatio=1&size=2200&ppi=300&palete=RGB&color=4294967295&maxKbs=5000&bColor=FFFFFFFF&fileType=jpg&strip=All","note":"Product and label snapshot verified October 6, 2026. Check the current package.","unitPrice":"61.4¢/oz","rating":4.6,"reviewCount":1704,"reviewText":"1,704 reviews","shortDescription":"18 count · 25 g per labeled serving","shoppingNotes":["Current manufacturer formulation has 7g dietary fiber. Do not copy older 6g formulation data.","Walmart-linked label photo shows 26% fiber DV; current manufacturer page and front pack photo say 25%. Required calories, dietary fiber grams and serving size agree. Prefer showing those agreed facts; do not conflate the inconsistent DV percent/iron values.","Prices and written-review counts are source snapshots, not live local offers."]},{"id":"zbar","name":"Zbar Chocolate Brownie Soft-Baked Energy Snack Bars, Organic Granola Bars, Snacks for Kids, 6ct","size":"6 count · 7.62 oz pack","cal":140,"fiber":3,"serving":"1 bar (36 g)","price":"5.82","tags":"fiber brownies chocolate baked snack ZBAR","image":"zbar-front-display.svg","photoSourceLabel":"Walmart","productSource":"https://www.walmart.com/ip/Zbar-Chocolate-Brownie-Soft-Baked-Snack-Bars-Non-GMO-10g-Whole-Grains-USDA-Organic-Granola-Bars-6-Pack/28646397","nutritionSource":"https://images.salsify.com/image/upload/s--0V4gOQp7--/dn_300/56fa57d31a65fbb71200eb1f600333c0a365fa5a.jpg","note":"Product and label snapshot verified October 6, 2026. Check the current package.","unitPrice":"76.6¢/oz","rating":4.6,"reviewCount":230,"reviewText":"230 reviews","shortDescription":"6 count · 36 g per labeled serving","shoppingNotes":["Exact verified flavor is Chocolate Brownie, not Iced Brownie. Do not label this Iced Brownie. Current Walmart hero packaging has Toy Story graphics.","Prices and written-review counts are source snapshots, not live local offers."]}];
const state={step:0,fiber:false,calories:false,minFiber:3,maxCal:100,query:'fiber brownies',panel:false,draftFiber:false};
const guides=["The supplied screenshot shows brand suggestions and a <strong>Protein Per Serving</strong> category. A fiber-grams control is not visible there. Open Filters to inspect the reference; this is not a full-app audit.", "Select <strong>Fiber</strong> and choose a <strong>minimum fiber amount per serving</strong>. Optionally select Low cal for a maximum calorie amount. Selecting a chip immediately applies its default. Edit an amount to update the matches.", "<strong>Both filters are selected.</strong> Edit either amount and inspect the matching rows. Each row shows fiber grams, calories and the labeled serving size. Clear one chip to compare a single-filter result."];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function matches(p,fiber=state.fiber,calories=state.calories){const words=state.query.toLowerCase().trim().split(/\s+/).filter(Boolean);return words.every(w=>(p.name+' '+p.tags).toLowerCase().includes(w))&&(!fiber||(Number.isFinite(p.fiber)&&p.fiber>=state.minFiber))&&(!calories||(Number.isFinite(p.cal)&&p.cal<=state.maxCal))}
const visible=()=>products.filter(p=>matches(p));
function facts(p){if(state.step===0||(!state.fiber&&!state.calories))return '';const parts=[];if(state.fiber)parts.push(`<strong>${p.fiber} g fiber</strong>`);if(state.calories)parts.push(`<strong>${p.cal} cal</strong>`);return `<p class="nutrient-summary compact" aria-label="Selected nutrition facts">${parts.join(' <span aria-hidden="true">·</span> ')} <span class="nutrient-serving">· ${esc(p.serving)} per serving</span></p>`}
function row(p,i){return `<article class="product" role="listitem"><div class="productimage"><img src="assets/${esc(p.image)}" alt="${esc(p.name)} package" width="573" height="573" loading="${i===0?'eager':'lazy'}"></div><div class="productdetails"><div class="producttop"><span class="price">$${esc(p.price.split('.')[0])}<sup>${esc(p.price.split('.')[1])}</sup></span><span class="unit-price">${esc(p.unitPrice)}</span></div><h3 title="${esc(p.name)}">${esc(p.name)}</h3><p class="short-description">${esc(p.shortDescription)}</p>${facts(p)}<div class="reviews" aria-label="${p.rating} out of 5 stars; ${esc(p.reviewText)}"><span class="stars" aria-hidden="true"><span>★★★★★</span><span class="filled-stars" style="width:${p.rating/5*100}%">★★★★★</span></span><span class="rating-number">${p.rating}</span><span class="review-count">${esc(p.reviewText)}</span></div><div class="demoaction"><button class="demoadd" disabled aria-label="Add to cart, display only">Add to cart</button></div></div></article>`}
const sourceNotes={"gv": "The serving label states 25 g; package and listing ounce amounts differ slightly (0.88 versus 0.89 oz). The demo uses the labeled serving weight.", "fiber-one": "The label and manufacturer agree on 7 g fiber, 70 calories and a 25 g serving. Their percent Daily Value differs, so that percentage is omitted.", "zbar": "This snapshot is for the Chocolate Brownie flavor, six-count pack."};
function sources(){return products.map(p=>`<li><strong>${esc(p.name)}</strong>: <a href="${esc(p.productSource)}" target="_blank" rel="noopener noreferrer">Walmart listing</a> · <a href="${esc(p.nutritionSource)}" target="_blank" rel="noopener noreferrer">nutrition label</a>. ${esc(p.note)} ${esc(sourceNotes[p.id]||'')}</li>`).join('')}
function updateApply(){$('apply').textContent=`View results (${visible().length})`}
function render(){$('demo').dataset.layout=state.step===0?'observed':'proposed';document.querySelectorAll('.step').forEach(b=>{if(Number(b.dataset.step)===state.step)b.setAttribute('aria-current','step');else b.removeAttribute('aria-current')});$('guideText').innerHTML=guides[state.step];if(state.step===2&&!(state.fiber&&state.calories))$('guideText').innerHTML=state.fiber?'<strong>Fiber</strong> is selected. Its minimum-grams control and matching per-serving amount are shown.':state.calories?'<strong>Low cal</strong> is selected. Its maximum-calories control and matching per-serving amount are shown.':'No nutrient filters are selected. Choose a chip to show its amount control.';$('guideNext').textContent=['Try the amount controls','Show a combined result','Restart walkthrough'][state.step];
for(const [id,key,label] of [['fiberChip','fiber','Fiber'],['lowCal','calories','Low cal']]){$(id).hidden=state.step===0;$(id).textContent=label;$(id).setAttribute('aria-pressed',String(state[key]));$(id).className='chip '+(state[key]?'active':'emphasis')}
const count=Number(state.fiber)+Number(state.calories);$('filters').className='chip'+(count?' active':'');$('filterBadge').hidden=!count;$('filterBadge').textContent=String(count);$('filters').setAttribute('aria-expanded',String(state.panel));
$('placementNote').textContent=state.step===0?'Observed: the screenshot shows brand suggestions, not a visible fiber-grams shortcut.':'Proposed: relevant nutrient chips in the main area. Chips wrap; no sideways scrolling needed.';
$('demoCutoffs').hidden=!count||state.step===0;$('nutrientField').hidden=!state.fiber;$('calorieField').hidden=!state.calories;$('fiberMinimum').disabled=!state.fiber;$('calorieMaximum').disabled=!state.calories;$('controlTitle').textContent=state.fiber&&state.calories?'Per-serving filters':state.fiber?'Fiber Per Serving':'Calories Per Serving';$('cutoffError').hidden=true;$('fiberMinimum').removeAttribute('aria-invalid');$('calorieMaximum').removeAttribute('aria-invalid');$('cutoffSummary').textContent=[state.fiber?`Minimum: ${state.minFiber} g fiber`:null,state.calories?`Maximum: ${state.maxCal} cal`:null].filter(Boolean).join(' · ')+' per serving';$('fiberMinimum').value=String(state.minFiber);$('calorieMaximum').value=String(state.maxCal);
$('selected').hidden=!count;$('selectedText').textContent=[state.fiber?`Fiber ≥ ${state.minFiber} g`:null,state.calories?`Calories ≤ ${state.maxCal}`:null].filter(Boolean).join(' · ')+' per serving';$('clear').textContent='Clear filters';
const list=visible();$('resultStatus').textContent=`${list.length} of ${products.length} sample products with linked sources`;$('products').innerHTML=list.length?list.map(row).join(''):'<div class="empty"><h3>No products match these demo cutoffs.</h3><p>Change the illustrative cutoff or clear a filter to see more products.</p><button class="primary" id="emptyReset">Reset demo search</button></div>';if($('emptyReset'))$('emptyReset').onclick=reset;
$('filterPanel').hidden=!state.panel;$('panelTitle').textContent='Filters';$('panelDescription').textContent='Suggested choices, simplified from the supplied fiber-brownie screenshot.';updateApply();
}
function changeStep(step){Object.assign(state,{step,fiber:step===2,calories:step===2,minFiber:3,maxCal:100,query:'fiber brownies',panel:false,draftFiber:step===2});$('query').value=state.query;render()}
function openPanel(){state.panel=true;state.draftFiber=state.fiber;render();$('closePanel').focus()}
function closePanel(){state.panel=false;state.draftFiber=state.fiber;render();$('filters').focus()}
function apply(){state.panel=false;render();$('filters').focus()}
function clear(){state.fiber=false;state.calories=false;state.draftFiber=false;render();$(state.step===0?'filters':'fiberChip').focus()}
function reset(){state.fiber=false;state.calories=false;state.draftFiber=false;state.query='fiber brownies';state.panel=false;state.minFiber=3;state.maxCal=100;$('query').value=state.query;render();$('query').focus()}
function applyNumericControls(event){
 if(event&&event.preventDefault)event.preventDefault();
 const changes={},errors=[];
 for(const [selected,id,field,isCalories] of [[state.fiber,'fiberMinimum','minFiber',false],[state.calories,'calorieMaximum','maxCal',true]]){
  if(!selected)continue;const raw=$ (id).value.trim(),value=Number(raw),max=isCalories?2000:100;
  if(raw===''||!Number.isFinite(value)||value<0||value>max||(isCalories&&!Number.isInteger(value))){$(id).setAttribute('aria-invalid','true');errors.push(isCalories?'Enter a whole-number calorie maximum from 0 to 2000.':'Enter a fiber minimum from 0 to 100 grams.')}else{changes[field]=value;$(id).removeAttribute('aria-invalid')}
 }
 if(errors.length){$('cutoffError').textContent=errors.join(' ');$('cutoffError').hidden=false;return false}
 Object.assign(state,changes);render();return true;
}
function configure(input){if(!input||typeof input!=='object'||Object.keys(input).some(k=>!['step','fiber','calories','minFiber','maxCal','query'].includes(k)))throw new Error('Invalid input');if(input.step!==undefined&&(!Number.isInteger(input.step)||input.step<0||input.step>2))throw new Error('Invalid step');for(const k of ['fiber','calories'])if(input[k]!==undefined&&typeof input[k]!=='boolean')throw new Error('Invalid filter');if(input.minFiber!==undefined&&(!Number.isFinite(input.minFiber)||input.minFiber<0||input.minFiber>100))throw new Error('Invalid fiber cutoff');if(input.maxCal!==undefined&&(!Number.isInteger(input.maxCal)||input.maxCal<0||input.maxCal>2000))throw new Error('Invalid calorie cutoff');if(input.query!==undefined&&(typeof input.query!=='string'||input.query.length>120))throw new Error('Invalid query');if(input.step!==undefined)changeStep(input.step);for(const k of ['fiber','calories','minFiber','maxCal','query'])if(input[k]!==undefined)state[k]=input[k];state.panel=false;state.draftFiber=state.fiber;$('query').value=state.query;render();return {step:state.step,fiber:state.fiber,calories:state.calories,minFiber:state.minFiber,maxCal:state.maxCal,matches:visible().length}}
 $('dataSources').innerHTML=sources();
 document.querySelectorAll('.step').forEach(b=>b.onclick=()=>changeStep(Number(b.dataset.step)));$('guideNext').onclick=()=>changeStep((state.step+1)%3);$('restart').onclick=()=>changeStep(0);$('filters').onclick=()=>state.panel?closePanel():openPanel();$('fiberChip').onclick=()=>{state.fiber=!state.fiber;state.draftFiber=state.fiber;state.panel=false;render()};$('lowCal').onclick=()=>{state.calories=!state.calories;state.panel=false;render()};$('closePanel').onclick=closePanel;$('cancel').onclick=closePanel;$('apply').onclick=apply;$('clear').onclick=clear;$('nutrientForm').onsubmit=applyNumericControls;$('fiberMinimum').onchange=applyNumericControls;$('calorieMaximum').onchange=applyNumericControls;$('searchForm').onsubmit=e=>{e.preventDefault();state.query=$('query').value.slice(0,120);state.panel=false;render()};document.addEventListener('keydown',e=>{if(e.key==='Escape'&&state.panel){e.preventDefault();closePanel()}});render();
 if(document.modelContext?.registerTool){const lifecycle=new AbortController();try{Promise.resolve(document.modelContext.registerTool({name:'configure_fiber_filter_demo',title:'Configure fiber-brownie filter demo',description:'Change only this independent demo. No real retailer account or cart is changed.',inputSchema:{type:'object',properties:{step:{type:'integer',minimum:0,maximum:2},fiber:{type:'boolean'},calories:{type:'boolean'},minFiber:{type:'number',minimum:0,maximum:100},maxCal:{type:'integer',minimum:0,maximum:2000},query:{type:'string',maxLength:120}},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:configure},{signal:lifecycle.signal})).catch(()=>{});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true})}catch{}}
 window.fiberDemo={configure,getState:()=>({...state,matches:visible().length})};

 if(window.location&&typeof URLSearchParams!=='undefined'){
  const q=new URLSearchParams(window.location.search),input={};
  if(q.has('step'))input.step=Number(q.get('step'));
  for(const key of ['fiber','calories'])if(q.has(key))input[key]=q.get(key)==='1'?true:q.get(key)==='0'?false:q.get(key);
  for(const key of ['minFiber','maxCal'])if(q.has(key))input[key]=Number(q.get(key));
  if(q.has('query'))input.query=q.get('query');
  try{configure(input);if(q.get('panel')==='filters')openPanel()}catch{}
 }
})();
